  reemploi:[
    {q:'Écrivez deux phrases concessives sur votre apprentissage du chinois : une difficulté, et ce que vous faites malgré elle.',
     verif:[{type:'contient',v:'虽然',msg:'La concession s’ouvre par 虽然.'},
            {type:'un_parmi',v:['但是','可是','不过'],msg:'Le chinois garde le second connecteur.'}],
     modeles:[{hz:'虽然汉字很难，但是我每天都写。',py:'suī rán Hàn zì hěn nán, dàn shì wǒ měi tiān dōu xiě',fr:'Bien que les caractères soient difficiles, j’en écris tous les jours.'},
              {hz:'我虽然学了三年，可是还是听不懂。',py:'wǒ suī rán xué le sān nián, kě shì hái shi tīng bu dǒng',fr:'Bien que j’aie appris trois ans, je ne comprends toujours pas.'}],
     criteres:['Les deux connecteurs sont présents','Sujet commun devant 虽然, non répété','Une virgule sépare les propositions']},
    {q:'Faites l’éloge d’un plat ou d’un lieu en renchérissant : 不但⋯而且, puis la même phrase avec 还.',
     verif:[{type:'contient',v:'不但',msg:'Le renchérissement s’ouvre par 不但.'},
            {type:'un_parmi',v:['而且','还','也'],msg:'On attend 而且, 还 ou 也.'}],
     modeles:[{hz:'这个菜不但很便宜，而且很好吃。',py:'zhè ge cài bú dàn hěn pián yi, ér qiě hěn hǎo chī',fr:'Ce plat est non seulement bon marché, mais aussi très bon.'},
              {hz:'这个菜不但很便宜，还很好吃。',py:'zhè ge cài bú dàn hěn pián yi, hái hěn hǎo chī',fr:'Ce plat est non seulement bon marché, mais aussi très bon.'}],
     criteres:['不但 n’appelle jamais 但是','还 et 也 se placent devant le verbe','Un seul connecteur par proposition']},
    {q:'Deux phrases avec le même moule 除了⋯以外 : une qui inclut, une qui exclut. Faites sentir que seul le second mot change.',
     verif:[{type:'contient',v:'除了',msg:'Le moule s’ouvre par 除了.'},
            {type:'contient',v:'都',msg:'Le sens « sauf » réclame 都.'}],
     modeles:[{hz:'除了汉语以外，我还学英语。',py:'chú le Hàn yǔ yǐ wài, wǒ hái xué Yīng yǔ',fr:'En plus du chinois, j’apprends l’anglais.'},
              {hz:'除了星期天以外，我每天都工作。',py:'chú le xīng qī tiān yǐ wài, wǒ měi tiān dōu gōng zuò',fr:'Sauf le dimanche, je travaille tous les jours.'}],
     criteres:['还 inclut ce qui précède','都 l’exclut','以外 ferme la première proposition']},
    {q:'Reprenez une de vos phrases concessives comme vous la diriez à une amie : sans 虽然, avec 不过, et sans 以外.',
     verif:[{type:'un_parmi',v:['不过','除了'],msg:'On attend 不过 ou 除了 sans 以外.'},
            {type:'absent',v:'以外',msg:'À l’oral, 以外 tombe.'}],
     modeles:[{hz:'很难，不过很有意思。',py:'hěn nán, bú guò hěn yǒu yì si',fr:'C’est dur, mais passionnant.'},
              {hz:'除了汉语，我还学英语。',py:'chú le Hàn yǔ, wǒ hái xué Yīng yǔ',fr:'À part le chinois, j’apprends aussi l’anglais.'}],
     criteres:['不过 remplace 但是','以外 disparaît','La virgule marque seule le retournement'],reg:'oral'}
  ]
