  fixes:[{seg:[{h:'你',p:'nǐ'},{h:'不得',p:'bù děi'},{h:'迟到',p:'chí dào'},P('。')],bad:1,bon:'你不能迟到。',why:'不得 n’existe pas : pour interdire, c’est 不能.'},{seg:[{h:'你',p:'nǐ'},{h:'不必须',p:'bú bì xū'},{h:'带',p:'dài'},{h:'护照',p:'hù zhào'},P('。')],bad:1,bon:'你不用带护照。',why:'必须 ne se nie pas : la dispense se dit 不用 ou 不必.'},{seg:[{h:'你',p:'nǐ'},{h:'不用',p:'bú yòng'},{h:'抽烟',p:'chōu yān'},P('。')],bad:1,bon:'你不能抽烟。',why:'Pour interdire, c’est 不能 ; 不用 ne fait que dispenser.'},{seg:[{h:'你',p:'nǐ'},{h:'多',p:'duō'},{h:'应该',p:'yīng gāi'},{h:'休息',p:'xiū xi'},P('。')],bad:1,bon:'你应该多休息。',why:'应该 se place devant tout le groupe verbal.'},{seg:[{h:'我',p:'wǒ'},{h:'得',p:'de'},{h:'走',p:'zǒu'},{h:'了',p:'le'},P('。')],bad:1,bon:'我得走了。',why:'Devant un verbe, 得 se lit děi : c’est un modal, non un complément de degré.'},{seg:[{h:'他',p:'tā'},{h:'跑',p:'pǎo'},{h:'得',p:'děi'},{h:'很快',p:'hěn kuài'},P('。')],bad:2,bon:'他跑得很快。',why:'Après un verbe, 得 est atone et introduit un jugement.'},{seg:[{h:'你',p:'nǐ'},{h:'应该',p:'yīng gāi'},{h:'不',p:'bù'},{h:'迟到',p:'chí dào'},P('。')],bad:2,bon:'你不应该迟到。',why:'La négation se place devant 应该, jamais entre le modal et le verbe.'},{seg:[{h:'学生',p:'xué sheng'},{h:'必须',p:'bì xū'},{h:'得',p:'děi'},{h:'交',p:'jiāo'},{h:'作业',p:'zuò yè'},P('。')],bad:2,bon:'学生必须交作业。',why:'Deux verbes modaux d’obligation ne se cumulent pas.'}],
  reemploi:[{q:'Donnez trois conseils à une amie fatiguée, avec 应该.',verif:[{type:'un_parmi',v:['应该','该'],msg:'Le conseil se dit 应该 ou 该.'},{type:'absent',v:'必须',msg:'Un conseil n’impose pas : 必须 serait trop fort.'}],modeles:[{hz:'你应该多休息，早点儿睡。',py:'nǐ yīng gāi duō xiū xi, zǎo diǎnr shuì',fr:'Tu devrais te reposer davantage et te coucher plus tôt.'},{hz:'你应该去看医生。',py:'nǐ yīng gāi qù kàn yī shēng',fr:'Tu devrais aller voir un médecin.'}],criteres:['应该 précède tout le groupe verbal','Le ton reste celui du conseil','Rien ne s’intercale entre 应该 et le verbe']},{q:'Écrivez trois obligations de votre semaine avec 得, puis les mêmes avec 要.',verif:[{type:'contient',v:'得',msg:'On attend 得 devant le verbe.'},{type:'contient',v:'要',msg:'On attend aussi la version avec 要.'}],modeles:[{hz:'明天我得加班。',py:'míng tiān wǒ děi jiā bān',fr:'Demain, je dois faire des heures supplémentaires.'},{hz:'星期五我要交报告。',py:'xīng qī wǔ wǒ yào jiāo bào gào',fr:'Vendredi, je dois rendre le rapport.'}],criteres:['得 se lit děi et précède le verbe','要 dit la même obligation, en plus neutre','Le repère de temps ouvre volontiers la phrase']},{q:'Écrivez trois phrases qui distinguent nettement dispenser, déconseiller et interdire.',verif:[{type:'contient',v:'不用',msg:'Il manque la dispense : 不用.'},{type:'contient',v:'不应该',msg:'Il manque le conseil négatif : 不应该.'},{type:'contient',v:'不能',msg:'Il manque l’interdiction : 不能.'},{type:'absent',v:'不得',msg:'不得 n’existe pas.'}],modeles:[{hz:'你不用买票，我已经买了。',py:'nǐ bú yòng mǎi piào, wǒ yǐ jīng mǎi le',fr:'Pas la peine d’acheter un billet, je l’ai déjà pris.'},{hz:'你不应该迟到，也不能在这儿抽烟。',py:'nǐ bù yīng gāi chí dào, yě bù néng zài zhèr chōu yān',fr:'Tu ne devrais pas être en retard, et tu n’as pas le droit de fumer ici.'}],criteres:['不用 dispense seulement','不应该 déconseille','不能 interdit','Aucun 不得 ni 不必须']},{q:'Prenez congé et refusez poliment une aide, comme vous le diriez à une amie.',verif:[{type:'un_parmi',v:['得','该'],msg:'On attend 我得走了 ou 该走了.'},{type:'un_parmi',v:['甭','不用'],msg:'Le refus poli se fait avec 不用 ou 甭.'}],modeles:[{hz:'我得走了，明天见。',py:'wǒ děi zǒu le, míng tiān jiàn',fr:'Il faut que j’y aille, à demain.'},{hz:'不用不用，我自己来。',py:'bú yòng bú yòng, wǒ zì jǐ lái',fr:'Non non, je m’en occupe.'}],criteres:['得 ou 该 ouvre le congé','了 ferme la phrase','不用 se redouble volontiers en refus'],reg:'oral'}]
